  <script>
    // Normalize Eastern Arabic (٠-٩) and Persian digits (۰-۹) to standard Western digits (0-9)
    function normalizeDigits(str) {
      return str
        .replace(/[٠-٩]/g, d => d.charCodeAt(0) - 1632)
        .replace(/[۰-۹]/g, d => d.charCodeAt(0) - 1776);
    }

    const otpInputs = Array.from(document.querySelectorAll('.otp-field'));
    const verifyBtn = document.getElementById('verify-btn');
    const timerDisplay = document.getElementById('timer-display');
    const countdownLabel = document.getElementById('countdown-label');
    const resendBtn = document.getElementById('resend-btn');
    const successModal = document.getElementById('success-modal');

    // Focus and input handling for 6 OTP boxes
    otpInputs.forEach((input, index) => {
      // Input event (digit entered)
      input.addEventListener('input', (e) => {
        const normalized = normalizeDigits(e.target.value).replace(/\D/g, '');

        if (normalized.length > 0) {
          input.value = normalized[0];
          input.classList.add('has-value');
          if (index < otpInputs.length - 1) {
            otpInputs[index + 1].focus();
          }
        } else {
          input.value = '';
          input.classList.remove('has-value');
        }
        updateVerifyState();
      });

      // Backspace & Arrow keys navigation
      input.addEventListener('keydown', (e) => {
        if (e.key === 'Backspace') {
          if (!input.value && index > 0) {
            otpInputs[index - 1].focus();
            otpInputs[index - 1].value = '';
            otpInputs[index - 1].classList.remove('has-value');
            updateVerifyState();
          } else {
            input.value = '';
            input.classList.remove('has-value');
            updateVerifyState();
          }
        } else if (e.key === 'ArrowLeft' && index > 0) {
          otpInputs[index - 1].focus();
        } else if (e.key === 'ArrowRight' && index < otpInputs.length - 1) {
          otpInputs[index + 1].focus();
        }
      });

      // Paste handling (e.g., copied from SMS)
      input.addEventListener('paste', (e) => {
        e.preventDefault();
        const clipboard = (e.clipboardData || window.clipboardData).getData('text');
        const digits = normalizeDigits(clipboard).replace(/\D/g, '').slice(0, 6);

        if (digits) {
          digits.split('').forEach((digit, i) => {
            if (otpInputs[i]) {
              otpInputs[i].value = digit;
              otpInputs[i].classList.add('has-value');
            }
          });
          const targetIndex = Math.min(digits.length, otpInputs.length - 1);
          otpInputs[targetIndex].focus();
          updateVerifyState();
        }
      });
    });

    function updateVerifyState() {
      const code = otpInputs.map(input => input.value).join('');
      const isComplete = code.length === 6;
      verifyBtn.disabled = !isComplete;
    }

    // Countdown logic
    let remainingSeconds = 45;
    let timerInterval = null;

    function startTimer() {
      clearInterval(timerInterval);
      remainingSeconds = 45;
      resendBtn.disabled = true;
      countdownLabel.textContent = 'إعادة الإرسال خلال';
      timerDisplay.style.display = 'inline-block';
      updateTimerDisplay();

      timerInterval = setInterval(() => {
        remainingSeconds--;
        updateTimerDisplay();

        if (remainingSeconds <= 0) {
          clearInterval(timerInterval);
          resendBtn.disabled = false;
          countdownLabel.textContent = 'لم يصلك الرمز؟';
          timerDisplay.style.display = 'none';
        }
      }, 1000);
    }

    function updateTimerDisplay() {
      const mins = Math.floor(remainingSeconds / 60);
      const secs = remainingSeconds % 60;
      const formatted = `${mins}:${secs < 10 ? '0' : ''}${secs}`;
      timerDisplay.innerHTML = `<bdi dir="ltr">${formatted}</bdi>`;
    }

    function handleResend() {
      if (resendBtn.disabled) return;

      // Clear inputs
      otpInputs.forEach(input => {
        input.value = '';
        input.classList.remove('has-value');
      });
      otpInputs[0].focus();
      updateVerifyState();

      // Restart countdown
      startTimer();
    }

    function handleVerify() {
      const code = otpInputs.map(input => input.value).join('');
      if (code.length === 6) {
        successModal.classList.add('active');
      }
    }

    function closeSuccessModal() {
      successModal.classList.remove('active');
    }

    // Initialize timer on load
    startTimer();
  </script>
